-----------------------------------------------------------------------
-- Nse NseCd OrderEntry Nnf 6.3 Formatting
-----------------------------------------------------------------------

-- absolute time base
local absolute_time_base_enum = {
  { 1, "Local", 0 },
  { 2, "Utc", 1 }
}

-- 0=Local, 1=Utc
nse_nsecd_orderentry_nnf_v6_3.absolute_time_base = 0

-- assumed connection role
local role_enum = {
  { 1, "Resolve from the conversation", 0 },
  { 2, "Initiator", 1 },
  { 3, "Acceptor", 2 }
}


-----------------------------------------------------------------------
-- Declare Dissection Options
-----------------------------------------------------------------------

local show = {}

-- Nse NseCd OrderEntry Nnf 6.3 Element Dissection Options
show.structs = true
show.application_messages = true
show.headers = true

-- Register Nse NseCd OrderEntry Nnf 6.3 Show Options
omi_nse_nsecd_orderentry_nnf_v6_3.prefs.acceptor_port = Pref.uint("Acceptor Port", 0, "Port the acceptor listens on; 0 resolves each frame's role from its conversation")
omi_nse_nsecd_orderentry_nnf_v6_3.prefs.assume_role = Pref.enum("Assume Role", 0, "Connection role assumed for every frame, for captures that start mid conversation", role_enum, false)
omi_nse_nsecd_orderentry_nnf_v6_3.prefs.swap_sides = Pref.bool("Swap Sides", false, "The first frame seen of each conversation was the acceptor's, not the initiator's; for captures that start mid conversation")
omi_nse_nsecd_orderentry_nnf_v6_3.prefs.show_structs = Pref.bool("Show Structs", show.structs, "Parse and add Structs to protocol tree")
omi_nse_nsecd_orderentry_nnf_v6_3.prefs.show_application_messages = Pref.bool("Show Application Messages", show.application_messages, "Parse and add Application Messages to protocol tree")
omi_nse_nsecd_orderentry_nnf_v6_3.prefs.show_headers = Pref.bool("Show Headers", show.headers, "Parse and add Headers to protocol tree")

omi_nse_nsecd_orderentry_nnf_v6_3.prefs.absolute_time_base = Pref.enum("Absolute Time Base", 0, "Render absolute times in Utc or in the reader's local time", absolute_time_base_enum, false)

-- Handle changed preferences
function omi_nse_nsecd_orderentry_nnf_v6_3.prefs_changed()

  -- Check if preferences have changed
  if show.application_messages ~= omi_nse_nsecd_orderentry_nnf_v6_3.prefs.show_application_messages then
    show.application_messages = omi_nse_nsecd_orderentry_nnf_v6_3.prefs.show_application_messages
  end
  if show.headers ~= omi_nse_nsecd_orderentry_nnf_v6_3.prefs.show_headers then
    show.headers = omi_nse_nsecd_orderentry_nnf_v6_3.prefs.show_headers
  end
  if show.structs ~= omi_nse_nsecd_orderentry_nnf_v6_3.prefs.show_structs then
    show.structs = omi_nse_nsecd_orderentry_nnf_v6_3.prefs.show_structs
  end
  if nse_nsecd_orderentry_nnf_v6_3.absolute_time_base ~= omi_nse_nsecd_orderentry_nnf_v6_3.prefs.absolute_time_base then
    nse_nsecd_orderentry_nnf_v6_3.absolute_time_base = omi_nse_nsecd_orderentry_nnf_v6_3.prefs.absolute_time_base
  end
end


-----------------------------------------------------------------------
-- Protocol Functions
-----------------------------------------------------------------------

-- trim trailing spaces
trim_right_spaces = function(str)
  local finish = str:len()

  while finish > 0 and str:byte(finish) == 0x20 do
    finish = finish - 1
  end

  return str:sub(1, finish)
end


