-- Account Number
nse_nsecd_orderentry_nnf_v6_3.account_number = {}

-- Size: Account Number
nse_nsecd_orderentry_nnf_v6_3.account_number.size = 10

-- Display: Account Number
nse_nsecd_orderentry_nnf_v6_3.account_number.display = function(value)
  return "Account Number: "..value
end

-- Dissect: Account Number
nse_nsecd_orderentry_nnf_v6_3.account_number.dissect = function(buffer, offset, packet, parent)
  local length = nse_nsecd_orderentry_nnf_v6_3.account_number.size
  local range = buffer(offset, length)
  local value = trim_right_spaces(range:string())
  local display = nse_nsecd_orderentry_nnf_v6_3.account_number.display(value, buffer, offset, packet, parent)

  parent:add(omi_nse_nsecd_orderentry_nnf_v6_3.fields.account_number, range, value, display)

  return offset + length, value
end

