-- Size: Entry Date Time
nse_nsecd_orderentry_nnf_v6_3.entry_date_time.size = 4

-- Dissect: Entry Date Time
nse_nsecd_orderentry_nnf_v6_3.entry_date_time.dissect = function(buffer, offset, packet, parent)
  local length = nse_nsecd_orderentry_nnf_v6_3.entry_date_time.size
  local range = buffer(offset, length)
  local value = range:int()

  -- A field's absolute time base is fixed when it is declared, so the
  -- protocol declares one per base and the preference picks between them
  local field = omi_nse_nsecd_orderentry_nnf_v6_3.fields.entry_date_time
  if nse_nsecd_orderentry_nnf_v6_3.absolute_time_base == 1 then field = omi_nse_nsecd_orderentry_nnf_v6_3.fields.entry_date_time_utc end

  local seconds = value + 315532800
  local nanos = 0
  parent:add(field, range, NSTime.new(seconds, nanos))

  return offset + length, value
end

