-- St Broker Eligibility Per Mkt
nse_nsecd_orderentry_nnf_v6_3.st_broker_eligibility_per_mkt = {}

-- Size: St Broker Eligibility Per Mkt
nse_nsecd_orderentry_nnf_v6_3.st_broker_eligibility_per_mkt.size = 2

-- Display: St Broker Eligibility Per Mkt
nse_nsecd_orderentry_nnf_v6_3.st_broker_eligibility_per_mkt.display = function(range, value, packet, parent)
  local flags = {}

  -- Is Oddlot Market flag set?
  if bit.band(value, 0x1000) ~= 0 then
    flags[#flags + 1] = "Oddlot Market"
  end
  -- Is Spot Market flag set?
  if bit.band(value, 0x2000) ~= 0 then
    flags[#flags + 1] = "Spot Market"
  end
  -- Is Auction Market flag set?
  if bit.band(value, 0x4000) ~= 0 then
    flags[#flags + 1] = "Auction Market"
  end
  -- Is Normal Market flag set?
  if bit.band(value, 0x8000) ~= 0 then
    flags[#flags + 1] = "Normal Market"
  end

  return table.concat(flags, "|")
end

-- Dissect Bit Fields: St Broker Eligibility Per Mkt
nse_nsecd_orderentry_nnf_v6_3.st_broker_eligibility_per_mkt.bits = function(range, value, packet, parent)

  -- Reserved 112: 12 Bit
  parent:add(omi_nse_nsecd_orderentry_nnf_v6_3.fields.reserved_112, range, value)

  -- Oddlot Market: 1 Bit
  parent:add(omi_nse_nsecd_orderentry_nnf_v6_3.fields.oddlot_market, range, value)

  -- Spot Market: 1 Bit
  parent:add(omi_nse_nsecd_orderentry_nnf_v6_3.fields.spot_market, range, value)

  -- Auction Market: 1 Bit
  parent:add(omi_nse_nsecd_orderentry_nnf_v6_3.fields.auction_market, range, value)

  -- Normal Market: 1 Bit
  parent:add(omi_nse_nsecd_orderentry_nnf_v6_3.fields.normal_market, range, value)
end

-- Dissect: St Broker Eligibility Per Mkt
nse_nsecd_orderentry_nnf_v6_3.st_broker_eligibility_per_mkt.dissect = function(buffer, offset, packet, parent)
  local size = nse_nsecd_orderentry_nnf_v6_3.st_broker_eligibility_per_mkt.size
  local range = buffer(offset, size)
  local value = range:uint()
  local display = nse_nsecd_orderentry_nnf_v6_3.st_broker_eligibility_per_mkt.display(range, value, packet, parent)
  local element = parent:add(omi_nse_nsecd_orderentry_nnf_v6_3.fields.st_broker_eligibility_per_mkt, range, display)

  if show.structs then
    nse_nsecd_orderentry_nnf_v6_3.st_broker_eligibility_per_mkt.bits(range, value, packet, element)
  end

  return offset + size, value
end

