-- Additional Order Flags
nse_nsecd_orderentry_nnf_v6_3.additional_order_flags = {}

-- Size: Additional Order Flags
nse_nsecd_orderentry_nnf_v6_3.additional_order_flags.size = 1

-- Display: Additional Order Flags
nse_nsecd_orderentry_nnf_v6_3.additional_order_flags.display = function(range, value, packet, parent)
  local flags = {}

  -- Is Col flag set?
  if bit.band(value, 0x02) ~= 0 then
    flags[#flags + 1] = "Col"
  end
  -- Is Stpc flag set?
  if bit.band(value, 0x10) ~= 0 then
    flags[#flags + 1] = "Stpc"
  end

  return table.concat(flags, "|")
end

