-- Dissect: Order Error Message
nse_nsecd_orderentry_nnf_v6_3.order_error_message.dissect = function(buffer, offset, packet, parent)
  if show.application_messages then
    -- Optionally add element to protocol tree
    parent = parent:add(omi_nse_nsecd_orderentry_nnf_v6_3.fields.order_error_message, buffer(offset, 0))
    local index = nse_nsecd_orderentry_nnf_v6_3.order_error_message.fields(buffer, offset, packet, parent)
    local length = index - offset
    parent:set_len(length)
    local display = nse_nsecd_orderentry_nnf_v6_3.order_error_message.display(packet, parent, length)
    parent:append_text(display)

    return index, parent
  else
    -- Skip element, add fields directly
    return nse_nsecd_orderentry_nnf_v6_3.order_error_message.fields(buffer, offset, packet, parent)
  end
end

