-- St Stock Eligible Indicators
nse_nsecd_orderentry_nnf_v6_3.st_stock_eligible_indicators = {}

-- Size: St Stock Eligible Indicators
nse_nsecd_orderentry_nnf_v6_3.st_stock_eligible_indicators.size = 2

-- Display: St Stock Eligible Indicators
nse_nsecd_orderentry_nnf_v6_3.st_stock_eligible_indicators.display = function(range, value, packet, parent)
  local flags = {}

  -- Is Books Merged flag set?
  if bit.band(value, 0x2000) ~= 0 then
    flags[#flags + 1] = "Books Merged"
  end
  -- Is Minimum Fill flag set?
  if bit.band(value, 0x4000) ~= 0 then
    flags[#flags + 1] = "Minimum Fill"
  end
  -- Is Aon flag set?
  if bit.band(value, 0x8000) ~= 0 then
    flags[#flags + 1] = "Aon"
  end

  return table.concat(flags, "|")
end

-- Dissect Bit Fields: St Stock Eligible Indicators
nse_nsecd_orderentry_nnf_v6_3.st_stock_eligible_indicators.bits = function(range, value, packet, parent)

  -- Reserved 113: 13 Bit
  parent:add(omi_nse_nsecd_orderentry_nnf_v6_3.fields.reserved_113, range, value)

  -- Books Merged: 1 Bit
  parent:add(omi_nse_nsecd_orderentry_nnf_v6_3.fields.books_merged, range, value)

  -- Minimum Fill: 1 Bit
  parent:add(omi_nse_nsecd_orderentry_nnf_v6_3.fields.minimum_fill, range, value)

  -- Aon: 1 Bit
  parent:add(omi_nse_nsecd_orderentry_nnf_v6_3.fields.aon, range, value)
end

-- Dissect: St Stock Eligible Indicators
nse_nsecd_orderentry_nnf_v6_3.st_stock_eligible_indicators.dissect = function(buffer, offset, packet, parent)
  local size = nse_nsecd_orderentry_nnf_v6_3.st_stock_eligible_indicators.size
  local range = buffer(offset, size)
  local value = range:uint()
  local display = nse_nsecd_orderentry_nnf_v6_3.st_stock_eligible_indicators.display(range, value, packet, parent)
  local element = parent:add(omi_nse_nsecd_orderentry_nnf_v6_3.fields.st_stock_eligible_indicators, range, display)

  if show.structs then
    nse_nsecd_orderentry_nnf_v6_3.st_stock_eligible_indicators.bits(range, value, packet, element)
  end

  return offset + size, value
end

