-- Dissect Fields: Server Message
nse_nsecd_orderentry_nnf_v6_3.server_message.fields = function(buffer, offset, packet, parent, size_of_server_message)
  local index = offset

  -- Message Header: Struct of 9 fields
  index, message_header = nse_nsecd_orderentry_nnf_v6_3.message_header.dissect(buffer, index, packet, parent)

  -- Dependency element: Transaction Code
  local transaction_code = buffer(index - 40, 2):int()

  -- Server Message Payload: Runtime Type with 66 branches
  index = nse_nsecd_orderentry_nnf_v6_3.server_message_payload.dissect(buffer, index, packet, parent, transaction_code)

  return index
end

-- Dissect: Server Message
nse_nsecd_orderentry_nnf_v6_3.server_message.dissect = function(buffer, offset, packet, parent, size_of_server_message)
  local index = offset + size_of_server_message

  -- Optionally add group/struct element to protocol tree
  if show.structs then
    parent = parent:add(omi_nse_nsecd_orderentry_nnf_v6_3.fields.server_message, buffer(offset, 0))
    local current = nse_nsecd_orderentry_nnf_v6_3.server_message.fields(buffer, offset, packet, parent, size_of_server_message)
    parent:set_len(size_of_server_message)
    local display = nse_nsecd_orderentry_nnf_v6_3.server_message.display(buffer, packet, parent)
    parent:append_text(display)

    return index, parent
  else
    -- Skip element, add fields directly
    nse_nsecd_orderentry_nnf_v6_3.server_message.fields(buffer, offset, packet, parent, size_of_server_message)

    return index
  end
end

-- Remaining Bytes For: Server Message
local server_message_bytes_remaining = function(buffer, index, available)
  -- Calculate the number of bytes remaining
  local remaining = available - index

  -- Check if packet size can be read
  if remaining < nse_nsecd_orderentry_nnf_v6_3.message_header.size then
    return -DESEGMENT_ONE_MORE_SEGMENT
  end

  -- Parse runtime size
  local current = buffer(index + 38, 2):int()

  -- Check if enough bytes remain
  if remaining < current then
    return -(current - remaining)
  end

  return remaining, current
end

-- Server Packet
nse_nsecd_orderentry_nnf_v6_3.server_packet = {}

-- Verify required size of Tcp packet
nse_nsecd_orderentry_nnf_v6_3.server_packet.requiredsize = function(buffer)
  return buffer:len() >= nse_nsecd_orderentry_nnf_v6_3.message_header.size
end

-- Dissect Server Packet
nse_nsecd_orderentry_nnf_v6_3.server_packet.dissect = function(buffer, packet, parent)
  local index = 0

  -- Dependency for Server Message
  local end_of_payload = buffer:len()

  -- Server Message: Struct of 2 fields
  while index < end_of_payload do

    -- Are minimum number of bytes are available?
    local available, size_of_server_message = server_message_bytes_remaining(buffer, index, end_of_payload)

    if available > 0 then
      -- Dissect this message within a buffer bounded to its own frame
      local frame = buffer(0, index + size_of_server_message):tvb()
      index = nse_nsecd_orderentry_nnf_v6_3.server_message.dissect(frame, index, packet, parent, size_of_server_message)
    else
      -- More bytes needed, so set packet information
      packet.desegment_offset = index
      packet.desegment_len = -(available)

      -- Claim the whole buffer: tcp keeps the bytes from desegment_offset for reassembly
      return end_of_payload
    end
  end

  return index
end

