-- Dissect Fields: Client Message
nse_nsecd_orderentry_nnf_v6_3.client_message.fields = function(buffer, offset, packet, parent, size_of_client_message)
  local index = offset

  -- Message Header: Struct of 9 fields
  index, message_header = nse_nsecd_orderentry_nnf_v6_3.message_header.dissect(buffer, index, packet, parent)

  -- Dependency element: Transaction Code
  local transaction_code = buffer(index - 40, 2):int()

  -- Client Message Payload: Runtime Type with 25 branches
  index = nse_nsecd_orderentry_nnf_v6_3.client_message_payload.dissect(buffer, index, packet, parent, transaction_code)

  return index
end

-- Dissect: Client Message
nse_nsecd_orderentry_nnf_v6_3.client_message.dissect = function(buffer, offset, packet, parent, size_of_client_message)
  local index = offset + size_of_client_message

  -- Optionally add group/struct element to protocol tree
  if show.structs then
    parent = parent:add(omi_nse_nsecd_orderentry_nnf_v6_3.fields.client_message, buffer(offset, 0))
    local current = nse_nsecd_orderentry_nnf_v6_3.client_message.fields(buffer, offset, packet, parent, size_of_client_message)
    parent:set_len(size_of_client_message)
    local display = nse_nsecd_orderentry_nnf_v6_3.client_message.display(buffer, packet, parent)
    parent:append_text(display)

    return index, parent
  else
    -- Skip element, add fields directly
    nse_nsecd_orderentry_nnf_v6_3.client_message.fields(buffer, offset, packet, parent, size_of_client_message)

    return index
  end
end

-- Remaining Bytes For: Client Message
local client_message_bytes_remaining = function(buffer, index, available)
  -- Calculate the number of bytes remaining
  local remaining = available - index

  -- Check if packet size can be read
  if remaining < nse_nsecd_orderentry_nnf_v6_3.message_header.size then
    return -DESEGMENT_ONE_MORE_SEGMENT
  end

  -- Parse runtime size
  local current = buffer(index + 38, 2):int()

  -- Check if enough bytes remain
  if remaining < current then
    return -(current - remaining)
  end

  return remaining, current
end

-- Client Packet
nse_nsecd_orderentry_nnf_v6_3.client_packet = {}

-- Verify required size of Tcp packet
nse_nsecd_orderentry_nnf_v6_3.client_packet.requiredsize = function(buffer)
  return buffer:len() >= nse_nsecd_orderentry_nnf_v6_3.message_header.size
end

-- Dissect Client Packet
nse_nsecd_orderentry_nnf_v6_3.client_packet.dissect = function(buffer, packet, parent)
  local index = 0

  -- Dependency for Client Message
  local end_of_payload = buffer:len()

  -- Client Message: Struct of 2 fields
  while index < end_of_payload do

    -- Are minimum number of bytes are available?
    local available, size_of_client_message = client_message_bytes_remaining(buffer, index, end_of_payload)

    if available > 0 then
      -- Dissect this message within a buffer bounded to its own frame
      local frame = buffer(0, index + size_of_client_message):tvb()
      index = nse_nsecd_orderentry_nnf_v6_3.client_message.dissect(frame, index, packet, parent, size_of_client_message)
    else
      -- More bytes needed, so set packet information
      packet.desegment_offset = index
      packet.desegment_len = -(available)

      -- Claim the whole buffer: tcp keeps the bytes from desegment_offset for reassembly
      return end_of_payload
    end
  end

  return index
end


-----------------------------------------------------------------------
-- Protocol Dissector and Components
-----------------------------------------------------------------------

-- Initialize Dissector
function omi_nse_nsecd_orderentry_nnf_v6_3.init()
end

-- Connection roles for Nse NseCd OrderEntry Nnf 6.3: Client is the initiator, Server is the acceptor
-- Initiator endpoint of each conversation, recorded from its first frame
local initiators = {}

-- Conversations whose first frame proved to be the acceptor's: the heuristic swaps the sides
local swapped = {}

-- Endpoint key of an address and port
local function endpoint(address, port)
  return tostring(address)..":"..tostring(port)
end


-- Conversation key, the same in both directions
local function conversation(packet)
  local source = endpoint(packet.src, packet.src_port)
  local destination = endpoint(packet.dst, packet.dst_port)

  if source < destination then
    return source.." "..destination
  end

  return destination.." "..source
end


-- Connection role of the frame's sender
nse_nsecd_orderentry_nnf_v6_3.role = function(packet)
  if omi_nse_nsecd_orderentry_nnf_v6_3.prefs.assume_role == 1 then
    return "initiator"
  end

  if omi_nse_nsecd_orderentry_nnf_v6_3.prefs.assume_role == 2 then
    return "acceptor"
  end

  local acceptor_port = omi_nse_nsecd_orderentry_nnf_v6_3.prefs.acceptor_port

  if acceptor_port ~= 0 and packet.dst_port == acceptor_port then
    return "initiator"
  end

  if acceptor_port ~= 0 and packet.src_port == acceptor_port then
    return "acceptor"
  end

  local key = conversation(packet)
  local sender = endpoint(packet.src, packet.src_port)

  if initiators[key] == nil then
    initiators[key] = sender
  end

  local sender_initiated = initiators[key] == sender

  if omi_nse_nsecd_orderentry_nnf_v6_3.prefs.swap_sides then
    sender_initiated = not sender_initiated
  end

  if swapped[key] then
    sender_initiated = not sender_initiated
  end

  if sender_initiated then
    return "initiator"
  end

  return "acceptor"
end


-- Swap the resolved sides of the frame's conversation
nse_nsecd_orderentry_nnf_v6_3.swap = function(packet)
  local key = conversation(packet)
  swapped[key] = not swapped[key]
end


-- Dissector for Nse NseCd OrderEntry Nnf 6.3
function omi_nse_nsecd_orderentry_nnf_v6_3.dissector(buffer, packet, parent)
  -- Set protocol name
  packet.cols.protocol = omi_nse_nsecd_orderentry_nnf_v6_3.name

  -- Dissect protocol
  local protocol = parent:add(omi_nse_nsecd_orderentry_nnf_v6_3, buffer(), omi_nse_nsecd_orderentry_nnf_v6_3.description, "("..buffer:len().." Bytes)")
  local role = nse_nsecd_orderentry_nnf_v6_3.role(packet)

  if role == "initiator" then
    return nse_nsecd_orderentry_nnf_v6_3.client_packet.dissect(buffer, packet, protocol)
  end

  return nse_nsecd_orderentry_nnf_v6_3.server_packet.dissect(buffer, packet, protocol)
end


